  console.log(`cap CLICKCLACK_WS_MAX_PAYLOAD_BYTES = ${CAP} bytes (1 MiB)`);
  await run("legit-json", JSON.stringify({ cursor: "c1", type: "message", body: "hi" }));
  await run("oversized-1MiB+1", "x".repeat(CAP + 1));
}

